import React, {
  useEffect,
  useRef,
  useState,
} from 'react';

import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiImage,
  FiHome,
  FiCheckCircle,
  FiGlobe,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';

import {
  getImageUrl,
} from '../../utils/helpers';

import {
  useLanguage,
} from '../../contexts/LanguageContext';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';


// ==========================================
// DEFAULT IMAGE
// ==========================================

const DEFAULT_IMG =
  '/default-avatar.png';


// ==========================================
// INITIAL FORM
// ==========================================

const initialForm = {
  name_en: '',
  name_km: '',

  acronym: '',

  tag_en: '',
  tag_km: '',

  description_en: '',
  description_km: '',

  features_en: '',
  features_km: '',

  is_active: true,
  order: 0,
};


// ==========================================
// ADMIN SCHOOLS
// ==========================================

const AdminSchools = () => {

  // ========================================
  // LANGUAGE
  // ========================================

  const {
    t,
    language,
  } = useLanguage();


  // ========================================
  // STATES
  // ========================================

  const [
    schools,
    setSchools,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    modalOpen,
    setModalOpen,
  ] = useState(false);


  const [
    editingSchool,
    setEditingSchool,
  ] = useState(null);


  const [
    formData,
    setFormData,
  ] = useState(initialForm);


  const [
    imageFile,
    setImageFile,
  ] = useState(null);


  const [
    submitting,
    setSubmitting,
  ] = useState(false);


  const fileRef =
    useRef(null);


  // ========================================
  // HELPER
  // ========================================

  const isKhmer =
    language === 'km' ||
    language === 'kh';


  const getSchoolName = (school) => {

    if (!school) {
      return '-';
    }

    if (isKhmer) {

      return (
        school.name_km ||
        school.name_en ||
        '-'
      );

    }

    return (
      school.name_en ||
      school.name_km ||
      '-'
    );

  };


  const getSchoolTag = (school) => {

    if (!school) {
      return '-';
    }

    if (isKhmer) {

      return (
        school.tag_km ||
        school.tag_en ||
        '-'
      );

    }

    return (
      school.tag_en ||
      school.tag_km ||
      '-'
    );

  };


  // ========================================
  // LOAD SCHOOLS
  // ========================================

  useEffect(() => {

    fetchSchools();

    // eslint-disable-next-line
  }, []);


  // ========================================
  // FETCH SCHOOLS
  // ========================================

  const fetchSchools = async () => {

    try {

      setLoading(true);


      const response =
        await api.get(
          '/api/schools/'
        );


      setSchools(
        Array.isArray(
          response.data
        )
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Fetch schools error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          t(
            'schools.loadFailed'
          )
        )
      );

    } finally {

      setLoading(false);

    }

  };


  // ========================================
  // RESET FORM
  // ========================================

  const resetForm = () => {

    setEditingSchool(null);

    setFormData({
      ...initialForm,
    });

    setImageFile(null);

    setSubmitting(false);


    if (fileRef.current) {

      fileRef.current.value = '';

    }

  };


  // ========================================
  // OPEN CREATE MODAL
  // ========================================

  const openCreateModal = () => {

    resetForm();

    setModalOpen(true);

  };


  // ========================================
  // CLOSE MODAL
  // ========================================

  const closeModal = () => {

    if (submitting) {
      return;
    }

    setModalOpen(false);

    resetForm();

  };


  // ========================================
  // INPUT CHANGE
  // ========================================

  const handleInputChange = (e) => {

    const {
      name,
      value,
      type,
      checked,
    } = e.target;


    setFormData(
      (prev) => ({
        ...prev,

        [name]:
          type === 'checkbox'
            ? checked
            : value,
      })
    );

  };


  // ========================================
  // IMAGE CHANGE
  // ========================================

  const handleImageChange = (e) => {

    const file =
      e.target.files?.[0];


    if (!file) {

      setImageFile(null);

      return;

    }


    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];


    if (
      !allowedTypes.includes(
        file.type
      )
    ) {

      toast.error(
        t(
          'schools.invalidImage'
        )
      );


      e.target.value = '';

      setImageFile(null);

      return;

    }


    if (
      file.size >
      5 * 1024 * 1024
    ) {

      toast.error(
        t(
          'schools.imageTooLarge'
        )
      );


      e.target.value = '';

      setImageFile(null);

      return;

    }


    setImageFile(file);

  };


  // ========================================
  // EDIT SCHOOL
  // ========================================

  const handleEdit = (school) => {

    setEditingSchool(
      school
    );


    setFormData({

      name_en:
        school.name_en || '',

      name_km:
        school.name_km || '',


      acronym:
        school.acronym || '',


      tag_en:
        school.tag_en || '',

      tag_km:
        school.tag_km || '',


      description_en:
        school.description_en || '',

      description_km:
        school.description_km || '',


      features_en:
        school.features_en || '',

      features_km:
        school.features_km || '',


      is_active:
        school.is_active ?? true,

      order:
        school.order ?? 0,

    });


    setImageFile(null);


    if (fileRef.current) {

      fileRef.current.value = '';

    }


    setModalOpen(true);

  };


  // ========================================
  // SUBMIT CREATE / UPDATE
  // ========================================

  const handleSubmit = async (e) => {

    e.preventDefault();


    // ======================================
    // VALIDATION
    // ======================================

    if (
      !formData.name_en.trim()
    ) {

      toast.error(
        'English school name is required.'
      );

      return;

    }


    try {

      setSubmitting(true);


      const fd =
        new FormData();


      // ====================================
      // ENGLISH
      // ====================================

      fd.append(
        'name_en',
        formData.name_en.trim()
      );


      fd.append(
        'tag_en',
        formData.tag_en || ''
      );


      fd.append(
        'description_en',
        formData.description_en || ''
      );


      fd.append(
        'features_en',
        formData.features_en || ''
      );


      // ====================================
      // KHMER
      // ====================================

      fd.append(
        'name_km',
        formData.name_km || ''
      );


      fd.append(
        'tag_km',
        formData.tag_km || ''
      );


      fd.append(
        'description_km',
        formData.description_km || ''
      );


      fd.append(
        'features_km',
        formData.features_km || ''
      );


      // ====================================
      // COMMON
      // ====================================

      fd.append(
        'acronym',
        formData.acronym || ''
      );


      fd.append(
        'is_active',
        String(
          formData.is_active
        )
      );


      fd.append(
        'order',
        String(
          Number(
            formData.order
          ) || 0
        )
      );


      // ====================================
      // IMAGE
      // ====================================

      if (imageFile) {

        fd.append(
          'image_file',
          imageFile
        );

      }


      // ====================================
      // UPDATE
      // ====================================

      if (editingSchool) {

        await api.put(
          `/api/schools/${editingSchool.id}`,
          fd
        );


        toast.success(
          t(
            'schools.updatedSuccess'
          )
        );

      }


      // ====================================
      // CREATE
      // ====================================

      else {

        await api.post(
          '/api/schools/',
          fd
        );


        toast.success(
          t(
            'schools.createdSuccess'
          )
        );

      }


      setModalOpen(false);

      resetForm();

      await fetchSchools();

    } catch (error) {

      console.error(
        'School submit error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          t(
            'schools.operationFailed'
          )
        )
      );

    } finally {

      setSubmitting(false);

    }

  };


  // ========================================
  // DELETE SCHOOL
  // ========================================

  const handleDelete = async (id) => {

    const confirmDelete =
      window.confirm(
        t(
          'schools.deleteConfirm'
        )
      );


    if (!confirmDelete) {
      return;
    }


    try {

      await api.delete(
        `/api/schools/${id}`
      );


      toast.success(
        t(
          'schools.deletedSuccess'
        )
      );


      await fetchSchools();

    } catch (error) {

      console.error(
        'Delete school error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          t(
            'schools.deleteFailed'
          )
        )
      );

    }

  };


  // ========================================
  // TABLE COLUMNS
  // ========================================

  const columns = [

    // ======================================
    // IMAGE
    // ======================================

    {
      key: 'image',

      label:
        t(
          'schools.image'
        ),

      render: (val) => (

        <div
          className="
            w-20
            h-14

            rounded-xl

            overflow-hidden

            border
            border-blue-200

            bg-blue-50

            shadow-sm
          "
        >

          <img
            src={
              getImageUrl(
                val,
                DEFAULT_IMG
              )
            }

            alt="School"

            className="
              w-full
              h-full
              object-cover
            "

            onError={(e) => {

              e.currentTarget.src =
                DEFAULT_IMG;

            }}
          />

        </div>

      ),
    },


    // ======================================
    // ACRONYM
    // ======================================

    {
      key: 'acronym',

      label:
        t(
          'schools.acronym'
        ),

      render: (val) => (

        <span
          className="
            inline-flex
            items-center
            justify-center

            min-w-[52px]

            px-3
            py-1.5

            rounded-lg

            bg-blue-50
            text-blue-900

            border
            border-blue-200

            text-xs
            font-bold
          "
        >

          {val || '-'}

        </span>

      ),
    },


    // ======================================
    // SCHOOL NAME
    // ======================================

    {
      key: 'name_en',

      label:
        t(
          'schools.schoolName'
        ),

      render: (_, row) => (

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-900

              flex-shrink-0
            "
          >

            <FiHome
              size={17}
            />

          </div>


          <div>

            <p
              className="
                font-semibold
                text-blue-900
              "
            >

              {
                getSchoolName(
                  row
                )
              }

            </p>


            {
              row.name_en &&
              row.name_km && (

                <p
                  className="
                    text-xs
                    text-blue-300
                    mt-0.5
                  "
                >

                  {
                    isKhmer
                      ? row.name_en
                      : row.name_km
                  }

                </p>

              )
            }

          </div>

        </div>

      ),
    },


    // ======================================
    // TAG
    // ======================================

    {
      key: 'tag_en',

      label:
        t(
          'schools.tag'
        ),

      render: (_, row) => (

        <span
          className="
            inline-flex

            px-3
            py-1.5

            rounded-full

            bg-blue-50
            text-blue-500

            text-xs
            font-medium
          "
        >

          {
            getSchoolTag(
              row
            )
          }

        </span>

      ),
    },


    // ======================================
    // ORDER
    // ======================================

    {
      key: 'order',

      label:
        t(
          'schools.displayOrder'
        ),

      render: (val) => (

        <span
          className="
            inline-flex
            items-center
            justify-center

            w-8
            h-8

            rounded-lg

            bg-blue-50
            text-blue-900

            font-semibold
            text-xs
          "
        >

          {val ?? 0}

        </span>

      ),
    },


    // ======================================
    // STATUS
    // ======================================

    {
      key: 'is_active',

      label:
        t(
          'common.status'
        ),

      render: (val) => (

        <span
          className={`
            inline-flex
            items-center
            gap-2

            px-3
            py-1.5

            rounded-full

            text-xs
            font-semibold

            border

            ${
              val
                ? `
                  bg-green-50
                  text-green-700
                  border-green-200
                `
                : `
                  bg-red-50
                  text-red-600
                  border-red-200
                `
            }
          `}
        >

          <span
            className={`
              w-2
              h-2
              rounded-full

              ${
                val
                  ? 'bg-green-500'
                  : 'bg-red-500'
              }
            `}
          />


          {
            val
              ? t(
                  'common.active'
                )
              : t(
                  'common.inactive'
                )
          }

        </span>

      ),
    },


    // ======================================
    // ACTIONS
    // ======================================

    {
      key: 'actions',

      label:
        t(
          'common.actions'
        ),

      render: (_, row) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleEdit(row)
            }

            title={
              t(
                'schools.editSchool'
              )
            }

            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-900

              hover:bg-blue-900
              hover:text-white

              transition-all
              duration-200
            "
          >

            <FiEdit2
              size={16}
            />

          </button>


          <button
            type="button"

            onClick={() =>
              handleDelete(
                row.id
              )
            }

            title={
              t(
                'schools.deleteSchool'
              )
            }

            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-red-50
              text-red-600

              hover:bg-red-600
              hover:text-white

              transition-all
              duration-200
            "
          >

            <FiTrash2
              size={16}
            />

          </button>

        </div>

      ),
    },

  ];


  // ========================================
  // RETURN
  // ========================================

  return (

    <div className="w-full">


      {/* ====================================
          PAGE HEADER
      ==================================== */}

      <div
        className="
          flex
          flex-col
          sm:flex-row

          sm:items-center
          sm:justify-between

          gap-4

          mb-7
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-12
              h-12

              flex
              items-center
              justify-center

              rounded-xl

              bg-blue-900
              text-white

              shadow-sm
            "
          >

            <FiHome
              size={22}
            />

          </div>


          <div>

            <h1
              className="
                text-3xl
                font-bold
                text-blue-900
                leading-tight
              "
            >

              {t(
                'schools.title'
              )}

            </h1>


            <p
              className="
                text-sm
                text-blue-400
                mt-1
              "
            >

              {t(
                'schools.subtitle'
              )}

            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            openCreateModal
          }

          className="
            inline-flex
            items-center
            justify-center
            gap-2

            h-11
            px-5

            bg-red-600
            hover:bg-red-700

            text-white

            rounded-xl

            text-sm
            font-semibold

            shadow-sm
            hover:shadow-md

            transition-all
            duration-200
          "
        >

          <FiPlus
            size={18}
          />


          {t(
            'schools.addSchool'
          )}

        </button>

      </div>


      {/* ====================================
          TABLE
      ==================================== */}

      <AdminCard
        className="
          overflow-hidden

          bg-white

          border
          border-blue-200

          rounded-2xl

          shadow-sm
        "
      >

        <AdminTable
          columns={columns}
          data={schools}
          loading={loading}
        />

      </AdminCard>


      {/* ====================================
          MODAL
      ==================================== */}

      <AdminModal
        isOpen={
          modalOpen
        }

        onClose={
          closeModal
        }

        title={
          editingSchool
            ? t(
                'schools.editSchool'
              )
            : t(
                'schools.createSchool'
              )
        }
      >

        <form
          onSubmit={
            handleSubmit
          }
        >

          <div className="space-y-6">


            {/* =================================
                ENGLISH SECTION
            ================================= */}

            <div
              className="
                border
                border-blue-200

                rounded-2xl

                overflow-hidden
              "
            >

              <div
                className="
                  flex
                  items-center
                  gap-2

                  px-4
                  py-3

                  bg-blue-50

                  border-b
                  border-blue-200
                "
              >

                <FiGlobe
                  className="text-blue-900"
                />


                <h3
                  className="
                    font-semibold
                    text-blue-900
                  "
                >
                  English
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-4

                  font-english
                "
              >

                {/* NAME */}

                <div>

                  <label className="admin-label">

                    School Name

                    <span className="text-red-600 ml-1">
                      *
                    </span>

                  </label>


                  <input
                    type="text"

                    name="name_en"

                    value={
                      formData.name_en
                    }

                    onChange={
                      handleInputChange
                    }

                    className="admin-input"

                    placeholder="Enter school name"

                    required
                  />

                </div>


                {/* TAG */}

                <div>

                  <label className="admin-label">
                    Tag
                  </label>


                  <input
                    type="text"

                    name="tag_en"

                    value={
                      formData.tag_en
                    }

                    onChange={
                      handleInputChange
                    }

                    className="admin-input"

                    placeholder="Example: Technology School"
                  />

                </div>


                {/* DESCRIPTION */}

                <div>

                  <label className="admin-label">
                    Description
                  </label>


                  <textarea
                    name="description_en"

                    value={
                      formData.description_en
                    }

                    onChange={
                      handleInputChange
                    }

                    rows="4"

                    className="
                      admin-input
                      resize-none
                    "

                    placeholder="Enter school description"
                  />

                </div>


                {/* FEATURES */}

                <div>

                  <label className="admin-label">
                    Features
                  </label>


                  <textarea
                    name="features_en"

                    value={
                      formData.features_en
                    }

                    onChange={
                      handleInputChange
                    }

                    rows="3"

                    className="
                      admin-input
                      resize-none
                    "

                    placeholder="Enter school features"
                  />

                </div>

              </div>

            </div>


            {/* =================================
                KHMER SECTION
            ================================= */}

            <div
              className="
                border
                border-blue-200

                rounded-2xl

                overflow-hidden
              "
            >

              <div
                className="
                  flex
                  items-center
                  gap-2

                  px-4
                  py-3

                  bg-blue-50

                  border-b
                  border-blue-200
                "
              >

                <FiGlobe
                  className="text-blue-900"
                />


                <h3
                  className="
                    font-semibold
                    text-blue-900
                    font-khmer
                  "
                >
                  ភាសាខ្មែរ
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-4
                  font-khmer
                "
              >

                {/* NAME KHMER */}

                <div>

                  <label className="admin-label">
                    ឈ្មោះសាលា
                  </label>


                  <input
                    type="text"

                    name="name_km"

                    value={
                      formData.name_km
                    }

                    onChange={
                      handleInputChange
                    }

                    className="
                      admin-input
                      font-khmer
                    "

                    placeholder="បញ្ចូលឈ្មោះសាលា"
                  />

                </div>


                {/* TAG KHMER */}

                <div>

                  <label className="admin-label">
                    ស្លាក
                  </label>


                  <input
                    type="text"

                    name="tag_km"

                    value={
                      formData.tag_km
                    }

                    onChange={
                      handleInputChange
                    }

                    className="
                      admin-input
                      font-khmer
                    "

                    placeholder="ឧទាហរណ៍៖ សាលាបច្ចេកវិទ្យា"
                  />

                </div>


                {/* DESCRIPTION KHMER */}

                <div>

                  <label className="admin-label">
                    ការពិពណ៌នា
                  </label>


                  <textarea
                    name="description_km"

                    value={
                      formData.description_km
                    }

                    onChange={
                      handleInputChange
                    }

                    rows="4"

                    className="
                      admin-input
                      resize-none
                      font-khmer
                    "

                    placeholder="បញ្ចូលការពិពណ៌នាអំពីសាលា"
                  />

                </div>


                {/* FEATURES KHMER */}

                <div>

                  <label className="admin-label">
                    លក្ខណៈពិសេស
                  </label>


                  <textarea
                    name="features_km"

                    value={
                      formData.features_km
                    }

                    onChange={
                      handleInputChange
                    }

                    rows="3"

                    className="
                      admin-input
                      resize-none
                      font-khmer
                    "

                    placeholder="បញ្ចូលលក្ខណៈពិសេសរបស់សាលា"
                  />

                </div>

              </div>

            </div>


            {/* =================================
                COMMON INFORMATION
            ================================= */}

            <div
              className="
                border
                border-blue-200

                rounded-2xl

                overflow-hidden
              "
            >

              <div
                className="
                  px-4
                  py-3

                  bg-blue-50

                  border-b
                  border-blue-200
                "
              >

                <h3
                  className="
                    font-semibold
                    text-blue-900
                  "
                >
                  {t(
                    'schools.generalInformation'
                  )}
                </h3>

              </div>


              <div
                className="
                  p-4
                  space-y-5
                "
              >

                {/* ACRONYM + ORDER */}

                <div
                  className="
                    grid
                    grid-cols-1
                    md:grid-cols-2
                    gap-4
                  "
                >

                  <div>

                    <label className="admin-label">

                      {t(
                        'schools.acronym'
                      )}

                    </label>


                    <input
                      type="text"

                      name="acronym"

                      value={
                        formData.acronym
                      }

                      onChange={
                        handleInputChange
                      }

                      className="admin-input"

                      placeholder="SC"
                    />

                  </div>


                  <div>

                    <label className="admin-label">

                      {t(
                        'schools.displayOrder'
                      )}

                    </label>


                    <input
                      type="number"

                      name="order"

                      min="0"

                      value={
                        formData.order
                      }

                      onChange={
                        handleInputChange
                      }

                      className="admin-input"
                    />

                  </div>

                </div>


                {/* =================================
                    IMAGE
                ================================= */}

                <div>

                  <label className="admin-label">

                    {t(
                      'schools.schoolImage'
                    )}

                  </label>


                  <div
                    onClick={() =>
                      fileRef.current?.click()
                    }

                    className="
                      group

                      border-2
                      border-dashed
                      border-blue-200

                      hover:border-blue-900

                      bg-blue-50

                      rounded-2xl

                      px-5
                      py-7

                      text-center

                      cursor-pointer

                      transition-all
                      duration-200
                    "
                  >

                    <input
                      ref={
                        fileRef
                      }

                      type="file"

                      accept="
                        image/jpeg,
                        image/png,
                        image/webp
                      "

                      onChange={
                        handleImageChange
                      }

                      className="hidden"
                    />


                    {
                      imageFile ? (

                        <div>

                          <div
                            className="
                              w-14
                              h-14

                              mx-auto
                              mb-3

                              flex
                              items-center
                              justify-center

                              rounded-xl

                              bg-white

                              text-blue-900

                              border
                              border-blue-200
                            "
                          >

                            <FiImage
                              size={25}
                            />

                          </div>


                          <p
                            className="
                              text-sm
                              font-semibold
                              text-blue-900
                              break-all
                            "
                          >

                            {
                              imageFile.name
                            }

                          </p>


                          <p
                            className="
                              text-xs
                              text-blue-400
                              mt-1
                            "
                          >

                            {t(
                              'schools.chooseAnotherImage'
                            )}

                          </p>

                        </div>

                      ) : (

                        <div>

                          {
                            editingSchool?.image ? (

                              <>

                                <img
                                  src={
                                    getImageUrl(
                                      editingSchool.image,
                                      DEFAULT_IMG
                                    )
                                  }

                                  alt="Current school"

                                  className="
                                    w-28
                                    h-20

                                    mx-auto
                                    mb-3

                                    object-cover

                                    rounded-xl

                                    border
                                    border-blue-200
                                  "

                                  onError={(e) => {

                                    e.currentTarget.src =
                                      DEFAULT_IMG;

                                  }}
                                />


                                <div
                                  className="
                                    inline-flex
                                    items-center
                                    gap-1.5

                                    px-3
                                    py-1.5

                                    rounded-full

                                    bg-white
                                    text-blue-900

                                    border
                                    border-blue-200

                                    text-xs
                                    font-medium
                                  "
                                >

                                  <FiCheckCircle />


                                  {t(
                                    'schools.keepCurrentImage'
                                  )}

                                </div>


                                <p
                                  className="
                                    text-xs
                                    text-blue-400
                                    mt-2
                                  "
                                >

                                  {t(
                                    'schools.uploadImage'
                                  )}

                                </p>

                              </>

                            ) : (

                              <>

                                <div
                                  className="
                                    w-14
                                    h-14

                                    mx-auto
                                    mb-3

                                    flex
                                    items-center
                                    justify-center

                                    rounded-xl

                                    bg-white

                                    border
                                    border-blue-200

                                    shadow-sm

                                    text-blue-400

                                    group-hover:text-blue-900
                                    group-hover:scale-105

                                    transition-all
                                  "
                                >

                                  <FiImage
                                    size={25}
                                  />

                                </div>


                                <p
                                  className="
                                    text-sm
                                    font-semibold
                                    text-blue-900
                                  "
                                >

                                  {t(
                                    'schools.uploadImage'
                                  )}

                                </p>


                                <p
                                  className="
                                    text-xs
                                    text-blue-400
                                    mt-1
                                  "
                                >

                                  JPG, PNG, WEBP — Max 5 MB

                                </p>

                              </>

                            )
                          }

                        </div>

                      )
                    }

                  </div>

                </div>


                {/* =================================
                    STATUS
                ================================= */}

                <div
                  className="
                    flex
                    items-center
                    justify-between

                    px-4
                    py-3.5

                    rounded-xl

                    bg-blue-50

                    border
                    border-blue-200
                  "
                >

                  <div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >

                      {t(
                        'schools.schoolStatus'
                      )}

                    </p>


                    <p
                      className="
                        text-xs
                        text-blue-400
                        mt-0.5
                      "
                    >

                      {t(
                        'schools.showOnWebsite'
                      )}

                    </p>

                  </div>


                  <label
                    className="
                      relative
                      inline-flex
                      items-center
                      cursor-pointer
                    "
                  >

                    <input
                      type="checkbox"

                      name="is_active"

                      checked={
                        formData.is_active
                      }

                      onChange={
                        handleInputChange
                      }

                      className="
                        sr-only
                        peer
                      "
                    />


                    <div
                      className="
                        relative

                        w-11
                        h-6

                        bg-blue-200

                        rounded-full

                        transition-colors

                        peer-checked:bg-blue-900

                        after:content-['']

                        after:absolute
                        after:top-[2px]
                        after:left-[2px]

                        after:w-5
                        after:h-5

                        after:bg-white

                        after:rounded-full

                        after:shadow-sm

                        after:transition-all

                        peer-checked:after:translate-x-full
                      "
                    />

                  </label>

                </div>

              </div>

            </div>

          </div>


          {/* =================================
              FOOTER BUTTONS
          ================================= */}

          <div
            className="
              mt-7
              pt-5

              border-t
              border-blue-200

              flex
              items-center
              justify-end

              gap-3
            "
          >

            <button
              type="button"

              onClick={
                closeModal
              }

              disabled={
                submitting
              }

              className="
                h-11

                px-5

                rounded-xl

                border
                border-blue-200

                bg-white

                text-blue-500

                text-sm
                font-semibold

                hover:bg-blue-50

                disabled:opacity-50
                disabled:cursor-not-allowed

                transition-all
                duration-200
              "
            >

              {t(
                'common.cancel'
              )}

            </button>


            <button
              type="submit"

              disabled={
                submitting
              }

              className="
                h-11

                inline-flex
                items-center
                justify-center
                gap-2

                px-6

                rounded-xl

                bg-red-600
                hover:bg-red-700

                text-white

                text-sm
                font-semibold

                shadow-sm
                hover:shadow-md

                disabled:opacity-60
                disabled:cursor-not-allowed

                transition-all
                duration-200
              "
            >

              {
                submitting
                  ? 'Saving...'
                  : editingSchool
                    ? (
                      <>

                        <FiEdit2
                          size={16}
                        />

                        {t(
                          'schools.updateSchool'
                        )}

                      </>
                    )
                    : (
                      <>

                        <FiPlus
                          size={17}
                        />

                        {t(
                          'schools.createSchool'
                        )}

                      </>
                    )
              }

            </button>

          </div>

        </form>

      </AdminModal>

    </div>

  );

};


export default AdminSchools;
